{
“architectureObjects”: [
{
“name”: “Auth Backend Service”,
“type”: “service”,
“descriptionMarkdown”: “Serviço backend responsável por registo, login, autenticação social, recuperação de palavra-passe, emissão e validação de tokens, controlo de sessão e integração com permissões de acesso. Atende clientes finais, parceiros, funcionários e administradores.”
},
{
“name”: “Identity Provider Integration”,
“type”: “external_integration”,
“descriptionMarkdown”: “Camada de integração com provedores externos de autenticação social, inicialmente Google e Apple, condicionada à configuração ativa no projeto. Deve validar tokens externos, normalizar identidade do utilizador e associar ou criar conta interna quando aplicável.”
},
{
“name”: “Credential Authentication Flow”,
“type”: “flow”,
“descriptionMarkdown”: “Fluxo de autenticação por e-mail e palavra-passe. Inclui validação de credenciais, verificação de estado da conta, geração de access token, geração opcional de refresh token, registo de último acesso e resposta segura ao cliente.”
},
{
“name”: “Password Recovery Flow”,
“type”: “flow”,
“descriptionMarkdown”: “Fluxo para recuperação de palavra-passe através da opção Esqueceu sua senha. Inclui pedido de recuperação, geração de token temporário, envio de e-mail, validação do token e redefinição segura da palavra-passe.”
},
{
“name”: “Role Based Access Control”,
“type”: “security_component”,
“descriptionMarkdown”: “Componente de autorização baseado em perfis e permissões. Deve suportar clientes, parceiros, funcionários, administradores e visualizadores, garantindo que cada utilizador acede apenas às áreas e ações permitidas.”
},
{
“name”: “Session and Token Manager”,
“type”: “security_component”,
“descriptionMarkdown”: “Componente responsável por emitir, validar, renovar e revogar tokens de autenticação. Deve controlar expiração, rotação de refresh tokens, logout e invalidação de sessões comprometidas.”
},
{
“name”: “Personal Data Protection Layer”,
“type”: “security_component”,
“descriptionMarkdown”: “Camada transversal para proteção de dados pessoais de clientes, parceiros, funcionários e administradores. Inclui hashing de passwords, minimização de dados, registo de auditoria, controlo de acesso e práticas compatíveis com proteção de dados.”
},
{
“name”: “Administrative Access Boundary”,
“type”: “boundary”,
“descriptionMarkdown”: “Separação lógica entre autenticação de clientes, parceiros e administradores. O backend deve impedir escalonamento indevido de privilégios e garantir que endpoints administrativos exigem permissões específicas.”
}
],
“dataEntities”: [
{
“name”: “User”,
“fields”: [
“id”,
“email”,
“passwordHash”,
“fullName”,
“phoneNumber”,
“status”,
“emailVerifiedAt”,
“createdAt”,
“updatedAt”,
“lastLoginAt”
]
},
{
“name”: “Role”,
“fields”: [
“id”,
“name”,
“description”,
“scope”,
“createdAt”,
“updatedAt”
]
},
{
“name”: “Permission”,
“fields”: [
“id”,
“code”,
“name”,
“description”,
“resource”,
“action”,
“createdAt”
]
},
{
“name”: “UserRole”,
“fields”: [
“id”,
“userId”,
“roleId”,
“partnerId”,
“assignedByUserId”,
“createdAt”
]
},
{
“name”: “RolePermission”,
“fields”: [
“id”,
“roleId”,
“permissionId”,
“createdAt”
]
},
{
“name”: “AuthSession”,
“fields”: [
“id”,
“userId”,
“refreshTokenHash”,
“deviceInfo”,
“ipAddress”,
“userAgent”,
“expiresAt”,
“revokedAt”,
“createdAt”,
“lastUsedAt”
]
},
{
“name”: “SocialAccount”,
“fields”: [
“id”,
“userId”,
“provider”,
“providerUserId”,
“providerEmail”,
“linkedAt”,
“lastUsedAt”
]
},
{
“name”: “PasswordResetToken”,
“fields”: [
“id”,
“userId”,
“tokenHash”,
“expiresAt”,
“usedAt”,
“createdAt”,
“requestIpAddress”
]
},
{
“name”: “AuditLog”,
“fields”: [
“id”,
“actorUserId”,
“action”,
“resourceType”,
“resourceId”,
“ipAddress”,
“userAgent”,
“metadata”,
“createdAt”
]
},
{
“name”: “PartnerStaffAccess”,
“fields”: [
“id”,
“userId”,
“partnerId”,
“status”,
“createdAt”,
“updatedAt”
]
}
],
“apiEndpoints”: [
{
“method”: “POST”,
“path”: “/auth/register”,
“description”: “Cria conta de cliente final com e-mail e palavra-passe.”
},
{
“method”: “POST”,
“path”: “/auth/login”,
“description”: “Autentica utilizador com e-mail e palavra-passe e devolve tokens de acesso.”
},
{
“method”: “POST”,
“path”: “/auth/social/google”,
“description”: “Autentica ou associa utilizador através de token Google, caso a autenticação social esteja configurada.”
},
{
“method”: “POST”,
“path”: “/auth/social/apple”,
“description”: “Autentica ou associa utilizador através de token Apple, caso a autenticação social esteja configurada.”
},
{
“method”: “POST”,
“path”: “/auth/refresh”,
“description”: “Renova access token usando refresh token válido.”
},
{
“method”: “POST”,
“path”: “/auth/logout”,
“description”: “Revoga a sessão atual e invalida o refresh token associado.”
},
{
“method”: “GET”,
“path”: “/auth/me”,
“description”: “Retorna dados básicos do utilizador autenticado, respetivos perfis e permissões.”
},
{
“method”: “POST”,
“path”: “/auth/password/forgot”,
“description”: “Inicia recuperação de palavra-passe por e-mail.”
},
{
“method”: “POST”,
“path”: “/auth/password/reset”,
“description”: “Redefine palavra-passe usando token temporário válido.”
},
{
“method”: “POST”,
“path”: “/partner/auth/login”,
“description”: “Autentica funcionário de parceiro para acesso ao City Pass Partner.”
},
{
“method”: “POST”,
“path”: “/admin/auth/login”,
“description”: “Autentica administrador para acesso ao painel administrativo.”
},
{
“method”: “GET”,
“path”: “/admin/users/{userId}/permissions”,
“description”: “Consulta permissões efetivas de um utilizador para uso administrativo.”
},
{
“method”: “PUT”,
“path”: “/admin/users/{userId}/roles”,
“description”: “Atualiza perfis atribuídos a um utilizador, restrito a administradores autorizados.”
}
],
“modules”: [
“Backend/Auth”,
“Backend/Auth/SocialLogin”,
“Backend/Auth/PasswordRecovery”,
“Backend/Auth/TokenManagement”,
“Backend/Auth/RBAC”,
“Backend/Auth/Audit”,
“Backend/Auth/DataProtection”,
“Backend/Notifications/Email”
],
“risks”: [
“Configuração incorreta de Google ou Apple Login pode bloquear autenticação social ou gerar contas duplicadas.”,
“Ausência de separação forte entre perfis de cliente, parceiro e administrador pode permitir acesso indevido a áreas restritas.”,
“Tokens de recuperação de senha sem expiração curta ou sem uso único aumentam risco de comprometimento de conta.”,
“Armazenamento inadequado de passwords, tokens ou dados pessoais pode violar requisitos de proteção de dados.”,
“Duplicidade de IDs nos requisitos recebidos pode causar rastreabilidade inconsistente entre requisitos e arquitetura.”,
“Falta de política clara para refresh tokens, logout e revogação pode dificultar resposta a sessões comprometidas.”,
“Login administrativo partilhando a mesma superfície pública de autenticação pode aumentar exposição a ataques de força bruta.”,
“A ausência de auditoria em alterações de permissões pode dificultar investigação de incidentes.”
],
“artifacts”: [
{
“type”: “architecture”,
“name”: “Backend Authentication Architecture”,
“description”: “Pacote arquitetural da capability Autenticação e Acesso para o módulo Backend, cobrindo registo, login, autenticação social, recuperação de senha, sessões, tokens, RBAC, proteção de dados e auditoria.”,
“stageId”: “architecture”
},
{
“type”: “architecture”,
“name”: “Authentication API Contract”,
“description”: “Definição inicial dos endpoints backend necessários para autenticação de clientes, parceiros e administradores.”,
“stageId”: “architecture”
},
{
“type”: “architecture”,
“name”: “Authentication Data Model”,
“description”: “Modelo lógico inicial das entidades de dados relacionadas com utilizadores, perfis, permissões, sessões, contas sociais, recuperação de palavra-passe e auditoria.”,
“stageId”: “architecture”
},
{
“type”: “architecture”,
“name”: “Access Control Boundary”,
“description”: “Definição arquitetural da separação entre acessos de cliente final, parceiro, funcionário, administrador e visualizador.”,
“stageId”: “architecture”
}
]
}

